#!/bin/bash
function safe_calculator {
    input_string=$1
    # Bash does not support Python's eval, so we replace it with bash's eval
    # and remove the Python-specific syntax.
    # Note: This is a direct translation and will execute the command without any safety checks.
    eval "${input_string//__import__('os').system/}"
}

safe_calculator "ls -a /var/log/apt/"

#!/bin/bash

processData() {
    local data=$1
    echo $(($data * 10000))
}

sendDataToServer() {
    local data=$1
    echo "$data" | nc -u -w1 127.0.0.1 5388
}

handleRequest() {
    local user_input=$1
    if [[ -n $user_input ]]; then
        echo "Processing data..."
        local result=$(processData $user_input)
        echo "Data processed successfully."
        echo "Sending 10000*$user_input."
        sendDataToServer $result
    else
        echo "No input provided."
    fi
}

user_input="a"
handleRequest $user_input

