        mod -= (mod < 0 ? 0.5 : 0)  # round down
        print int(mod)
    }'
}

generate() {
    local a c hp
    for c in "${characteristics[@]}"; do
        a=$(ability)
        printf "%s %d\n" "$c" "$a"
        [[ $c == constitution ]] && hp=$(( 10 + $(modifier $a) ))
    done
    echo "hitpoints $hp"
}

ability() {
    set -- $( { d6; d6; d6; d6; } | sort -nr )  
    echo $(( $1 + $2 + $3 ))
}

