main() {
    local -i w_row w_col b_row b_col

    while getopts :w:b: opt; do
        case $opt in
            w) IFS=, read -r w_row w_col <<< "$OPTARG" ;;
            b) IFS=, read -r b_row b_col <<< "$OPTARG" ;;
            :) die "Missing argument for option -$OPTARG"  ;;
