abs() { echo $(( $1 < 0 ? -$1 : $1 )); }

validate() {
    local player=$1
    local -i row=$2 col=$3

    (( row < 0 )) && die "$player row not positive"
    (( row > 7 )) && die "$player row not on board"
    (( col < 0 )) && die "$player column not positive"
    (( col > 7 )) && die "$player column not on board"
}

