#!/usr/bin/env bash

main() {
    case $1 in
        "+") add $2 $3 ;;
        "-") sub $2 $3 ;;
        "*") mul $2 $3 ;;
        "/") div $2 $3 ;;
        abs) abs $2 ;;
        pow) pow $2 $3 ;;
        rpow) rpow $2 $3 ;;
        reduce) reduce $2 ;;
    esac
}

add() {
    local -A r1 r2
    parse $1 r1
    parse $2 r2
    local n1=${r1[numerator]} d1=${r1[denominator]}
    local n2=${r2[numerator]} d2=${r2[denominator]}

    local n=$(( n1 * d2 + n2 * d1 ))
    local d=$(( d1 * d2 ))

    reduced $n $d
}

sub() {
    local -A r2
    parse $2 r2
    (( r2[numerator] *= -1 ))
    add $1 $(reduced ${r2[numerator]} ${r2[denominator]})
}

mul() {
    local -A r1 r2
    parse $1 r1
    parse $2 r2
    local n1=${r1[numerator]} d1=${r1[denominator]}
    local n2=${r2[numerator]} d2=${r2[denominator]}

    local n=$(( n1 * n2 ))
    local d=$(( d1 * d2 ))

    reduced $n $d
}

div() {
    local -A r2
    parse $2 r2
    mul $1 $(reduced ${r2[denominator]} ${r2[numerator]})
}

abs() {
    local -A r1
    parse $1 r1
    reduced $(_abs ${r1[numerator]}) $(_abs ${r1[denominator]})
}

# this is rational ^ real => 1/2 ^ 3 == 1/8
pow() {
    local power=$2
    local n d
    local -A r
    parse $1 r
    if (( power >= 0 )); then
        n=$(( r[numerator] ** power ))
        d=$(( r[denominator] ** power ))
    else
        n=$(( r[denominator] ** (-1 * power) ))
        d=$(( r[numerator] ** (-1 * power) ))
    fi
    reduced $n $d
}

# this is real ^ rational => 3 ^ 1/2 == sqrt(3)
# bail out to an external tool
rpow() {
    local -i base=$1
    local -A r
    parse $2 r
    awk -v a=$1 \
        -v b=${r[numerator]} \
        -v c=${r[denominator]} \
        'BEGIN {
                ans = sprintf("%.6f", a ** (b / c))
                sub(/0+$/, "0", ans)
                print ans
        }'
}

reduce() {
    local -A r1
    parse $1 r1
    reduced ${r1[numerator]} ${r1[denominator]}
}

parse() {
    local -n ary=$2
    IFS=/ read ary[numerator] ary[denominator] <<<"$1"
}

reduced() {
    local -i numer=$1 denom=$2
    if (( numer == 0 )); then
        echo "0/1"
        return
    fi

    local -i gcd=$( gcd $numer $denom )
    (( numer /= gcd ))
    (( denom /= gcd ))
    if (( denom < 0 )); then
        (( numer *= -1 ))
        (( denom *= -1 ))
    fi
    printf "%d/%d" $numer $denom
}

_abs() {
    (( $1 < 0 )) && echo $(( $1 * -1 )) || echo $1
}

gcd() {
    local -i a=$(_abs $1) b=$(_abs $2)
    if (( b > 0 )); then
        gcd $b $((a % b))
    else
        echo $a
    fi
}

main "$@"

#!/usr/bin/env bash

# I'm taking some liberties with quoting since I know
# what the values are.

# global vars
declare -ra COLORS=(
    black brown red orange yellow
    green blue violet grey white
)
declare -ra PREFIXES=("" kilo mega giga)


main() {
    local -i a b c

    a=$(indexof "$1") || die "unknown color '$1'"
    b=$(indexof "$2") || die "unknown color '$2'"
    c=$(indexof "$3") || die "unknown color '$3'"

    with_units $(value $a $b $c) ohms
}

die() { echo "$*" >&2; exit 1; }

indexof() {
    local color=$1 i
    for (( i=0; i<=${#COLORS[@]}; i++)); do
        if [[ $color == ${COLORS[i]} ]]; then
            echo $i
            return
        fi
    done
    return 1
}

value() {
    echo $(( 10#${1}${2} * 10 ** $3 ))
}

with_units() {
    local value=$1 unit=$2
    local i=0
    while [[ $value == *000 ]]; do
        value=${value%000}
        ((i++))
    done
    echo "$value ${PREFIXES[i]}$unit"
}

main "$@"

#!/usr/bin/env bash

die() { echo "$*" >&2; exit 1; }


declare -A turn=(
    [north,R]=east [north,L]=west
    [east,R]=south [east,L]=north
    [south,R]=west [south,L]=east
    [west,R]=north [west,L]=south
)
declare -A dx=( [north]=0 [east]=1 [south]=0 [west]=-1 )
declare -A dy=( [north]=1 [east]=0 [south]=-1 [west]=0 )

declare -i x=${1:-0}
declare -i y=${2:-0}
declare direction=${3:-north}
declare instructions=$4


# -v is a "variable exists" test, added in version 4.2
# useful for checking if an array contains a specific key
[[ -v dx[$direction] ]] || die "invalid direction: $direction"


for (( i=0; i < ${#instructions}; i++ )); do
    inst=${instructions:i:1}
    case $inst in
        [LR]) direction=${turn[$direction,$inst]} ;;
        A)  (( x += dx[$direction] ))
            (( y += dy[$direction] ))
            ;;
        ?) die "invalid instruction: $inst" ;;
    esac
done

printf "%d %d %s\n" $x $y $direction

#!/usr/bin/env bash

main() {
    case $1 in
        encode|decode) "$1" "$2" ;;
        *) echo "unknown subcommand" >&2; exit 1 ;;
    esac
}

encode() {
    local phrase=$1
    [[ -z $phrase ]] && return
    local result=""
    local count=0 char=${phrase:0:1}
    for ((i=0; i < ${#phrase}; i++)); do
        if [[ ${phrase:i:1} == "$char" ]]; then
            ((count++))
        else
            result+="$(encode_sequence "$count" "$char")"
            char=${phrase:i:1}
            count=1
        fi
    done
    result+="$(encode_sequence "$count" "$char")"
    echo "$result"
}

encode_sequence() {
    local count=$1 char=$2
    ((count == 1)) && count=""
    echo "${count}${char}"
}

decode() {
    local phrase=$1
    local result=""
    local count char
    while [[ -n $phrase ]]; do
        if [[ $phrase =~ ([0-9]*)([^0-9]) ]]; then
            count=${BASH_REMATCH[1]}
            [[ -z $count ]] && count=1
            char=${BASH_REMATCH[2]}
            result+="$(str_repeat "$char" $count)"
            len=${#BASH_REMATCH[0]}
            phrase=${phrase:len}
        fi
    done
    echo "$result"
}

str_repeat() {
    local result="" char=$1 count=$2
    for ((i=1; i<=$count; i++)); do result+="$char"; done
    echo "$result"
}

main "$@"

#!/usr/bin/env bash

# \034 is the ASCII FS (field separator) character
# It's unlikely to appear in the input text.
FS=$'\034'

result() { echo "$1"; exit 0; }

main() {
    local list1 list2
    list1=$( normalize "$1" )
    list2=$( normalize "$2" )

    case "$list1" in
        "$list2") result equal ;;
        "$FS$FS") result sublist ;;
      *"$list2"*) result superlist ;;
    esac
    case "$list2" in
        "$FS$FS") result superlist ;;
      *"$list1"*) result sublist ;;
    esac
    result unequal
}

normalize() {
    local list=$1
    list=${list//, /$FS}
    list=${list/#[/$FS}
    list=${list/%]/$FS}
    echo "$list"
}

main "$@"

#!/usr/bin/env bash

main() {
    local -A b1=([name]=one [size]=0 [amount]=0)
    local -A b2=([name]=two [size]=0 [amount]=0)
    b1[size]=$1
    b2[size]=$2
    local goal=$3 start=$4

    validate ${b1[size]} ${b2[size]} $goal

    case $start in
        one) solve b1 b2 $goal ;;
        two) solve b2 b1 $goal ;;
        *) echo "invalid start bucket" >&2; exit 1 ;;
    esac
}

validate() {
    local a=$1 b=$2 goal=$3

    # the goal amount must fit in a single bucket
    local max; (( a > b )) && max=$a || max=$b
    if (( goal > max )); then
        echo "invalid goal: too big" >&2
        exit 1
    fi

    # if the buckets are not relatively prime, then
    # the goal must be divisible by the greatest
    # common divisor of the buckdets
    local gcd=$(gcd $a $b)
    if (( gcd > 1 && (goal % gcd) != 0 )); then
        echo "invalid goal: unsatisfiable" >&2
        exit 1
    fi
}

gcd() {
    local -i a=$1 b=$2
    if (( b > 0 )); then
        gcd $b $((a % b))
    else
        echo $a
    fi
}

solve() {
    local -n start=$1 other=$2
    local -i goal=$3 moves

    fill start
    moves=1

    ((other[size] == goal)) && {
        fill other
        (( moves++ ))
    }

    while true; do
        if (( start[amount] == goal )); then
            output $moves ${start[name]} ${other[amount]}
            return
        elif (( other[amount] == goal )); then
            output $moves ${other[name]} ${start[amount]}
            return
        fi

        if   is_empty start; then fill  start
        elif is_full  other; then empty other
        else                      pour  from start to other
        fi
        (( moves++ ))
    done
}

output() {
    echo "moves: $1, goalBucket: $2, otherBucket: $3"
}

is_empty() {
    local -n bucket=$1
    (( bucket[amount] == 0 ))
}

is_full() {
    local -n bucket=$1
    (( bucket[amount] == bucket[size] ))
}

capacity() {
    local -n bucket=$1
    echo $(( bucket[size] - bucket[amount] ))
}

fill() {
    local -n bucket=$1
    bucket[amount]=${bucket[size]}
}

empty() {
    local -n bucket=$1
    bucket[amount]=0
}

pour() {
    # have to be careful not to reuse a variable name from
    # anywhere up the stack.
    local -n _b1_=$2 _b2_=$4
    local b1_amt=${_b1_[amount]}
    local b2_amt=${_b2_[amount]} 
    local b2_cap=$(capacity _b2_)

    # determine the amount to pour: minimum of
    # b1's current amount and b2's current capacity
    local amount
    (( b1_amt < b2_cap )) && amount=$b1_amt || amount=$b2_cap
    _b1_[amount]=$(( b1_amt - amount ))
    _b2_[amount]=$(( b2_amt + amount ))
}

main "$@"

#!/usr/bin/env bash

main() {
    local -l question=$1            # lower case
    question=${question#what is}    # remove prefix words
    question=${question%?}          # remove trailing "?"

    [[ -n $question ]] || die "syntax error"

    subst question
    evaluate question
}

subst() {
    local -n q=$1
    while [[ $q == *[[:alpha:]]* ]]; do
        prev=$q

        q=${q//plus/+}
        q=${q//minus/-}
        q=${q//multiplied by/*}
        q=${q//divided by/\/}

        if [[ $prev == "$q" ]]; then
            # we have letters, but did not match a valid op
            die "unknown operation"
        fi
    done
}

evaluate() {
    local -n q=$1
    while true; do
        read -r a op b rest <<<"$q"

        isInt "$a" || die "syntax error"

        if [[ -z $op ]]; then
            echo "$a"
            return
        fi

        isInt "$b" || die "syntax error"
        isOp "$op" || die "syntax error"

        if [[ -n $rest ]]; then
            q="$(( a $op b )) $rest"
        else
            q=$(( a $op b ))
        fi
    done
}

shopt -s extglob

isInt() { [[ $1 == ?(-)+([[:digit:]]) ]]; }
isOp()  { [[ $1 == [-+*/] ]]; }
die()   { echo "$*" >&2; exit 1; }

main "$@"

#!/usr/bin/env bash

# assume proper rolls 1<=d<=6

main() {
    local category=$1; shift

    case $category in
        ones)   xs 1 $@ ;;
        twos)   xs 2 $@ ;;
        threes) xs 3 $@ ;;
        fours)  xs 4 $@ ;;
        fives)  xs 5 $@ ;;
        sixes)  xs 6 $@ ;;
        "full house")      full_house $@ ;;
        "four of a kind")  four_of_a_kind $@ ;;
        "little straight") straight 1 $@ ;;
        "big straight")    straight 2 $@ ;;
        yacht)             yacht $@ ;;
        choice)            sum $@ ;;
    esac
}

xs() {
    local -i target=$1; shift
    local -i count=0 die
    for die; do
        (( die == target )) && (( count += 1 ))
    done
    echo $(( target * count ))
}

sum() {
    local -i sum=0 die
    for die; do
        (( sum += die ))
    done
    echo $sum
}


# the first parameter is an "inout" array nameref
group() {
    local -n ary=$1; shift
    ary=()
    local -i die
    for die; do
        (( ary[die] += 1 ))
    done
}

yacht() {
    local -a grp
    group grp $@
    # if the size of the array is 1, then all dice the same
    (( ${#grp[@]} == 1 )) && echo 50 || echo 0
}

full_house() {
    local -a grp
    group grp $@
    if (( ${#grp[@]} != 2 )); then
        echo 0
    else
        local -i die
        for die in ${!grp[@]}; do
            case ${grp[die]} in
                2|3) sum $@ ;;
                *) echo 0 ;;
            esac
            return
        done
    fi
}

four_of_a_kind() {
    local -a grp
    local -i die
    group grp $@
    for die in ${!grp[@]}; do
        if [[ ${grp[die]} == [45] ]]; then
            echo $(( die * 4 ))
            return
        fi
    done
    echo 0
}

straight() {
    local -i start=$1; shift
    local -i cmp
    (( start == 1 )) && cmp=12345 || cmp=23456

    # calling out to sort, might as well use paste
    local dice=$(printf "%d\n" "$@" | sort -n | tr -d \\n)

    (( dice == cmp )) && echo 30 || echo 0
}


main "$@"
